/**
 * DEVELOPMENT ONLY. Seeds a realistic demo marketplace with fake businesses,
 * orders and partner history. Never run this against production.
 *
 * Seeds a realistic demo marketplace. History is generated by running the real
 * order, renewal and payout services at back-dated times, so every number in
 * the demo follows the same business rules as live data.
 *
 * Prices are placeholders: the brief notes final prices follow supplier choice.
 */
import { and, eq } from "drizzle-orm";
import { closeDb, db } from "@/server/db/client";
import { single } from "@/server/db/query";
import * as t from "@/server/db/schema";
import { hashPassword } from "@/server/auth/password";
import { setMailer } from "@/server/mail/mailer";
import { setPaymentGateway } from "@/server/payments";
import { TestPaymentGateway } from "@/server/payments/test-gateway";
import { addDays } from "@/domain/pricing";
import { checkout, placePartnerBulkOrder, renewSubscription, startTrial } from "@/server/services/order.service";
import { generatePayouts, markPayoutPaid } from "@/server/services/payout.service";
import { seedCatalogue } from "./bootstrap";

setMailer({ send: async () => {} }); // keep seeding quiet
setPaymentGateway(new TestPaymentGateway()); // demo history never touches a real provider

const NOW = new Date();
const daysAgo = (days: number) => addDays(NOW, -days);

async function main() {
  if ((await db.select({ id: t.users.id }).from(t.users).limit(1)).length > 0) {
    console.log("Database already has data. Run `npm run db:reset` to start fresh.");
    return;
  }

  // Reference data first (the same code production uses), then demo history.
  await seedCatalogue(db);
  const productsBySlug = new Map((await db.select().from(t.products)).map((p) => [p.slug, p]));
  const allPlans = await db.select().from(t.plans);
  const plansBySlug = new Map([...productsBySlug.values()].map((p) => [p.slug, allPlans.filter((plan) => plan.productId === p.id)]));
  const product = (slug: string) => productsBySlug.get(slug)!;
  const plan = (slug: string, interval: "month" | "year") => plansBySlug.get(slug)!.find((p) => p.interval === interval)!;

  /* -------------------------------------------------------------- people */
  const passwordHash = {
    admin: await hashPassword("Admin@12345"),
    partner: await hashPassword("Partner@12345"),
    client: await hashPassword("Client@12345"),
  };

  const admin = await single(
    db.insert(t.users).values({ email: "admin@corpus365.test", name: "Corpus365 Admin", role: "admin", passwordHash: passwordHash.admin }).returning(),
  );

  async function createPartner(p: {
    email: string; name: string; city: string; region: string; code: string; profession: string;
    status: "approved" | "pending"; approvedDaysAgo?: number;
  }) {
    const joined = daysAgo((p.approvedDaysAgo ?? 3) + 5);
    const user = await single(
      db
        .insert(t.users)
        .values({ email: p.email, name: p.name, role: "partner", passwordHash: passwordHash.partner, city: p.city, phone: "+91 98470 00000", createdAt: joined })
        .returning(),
    );
    await db.insert(t.partnerProfiles).values({
      userId: user.id,
      code: p.code,
      status: p.status,
      profession: p.profession,
      region: p.region,
      agreementAcceptedAt: joined,
      approvedAt: p.approvedDaysAgo !== undefined ? daysAgo(p.approvedDaysAgo) : null,
      payoutUpi: p.status === "approved" ? `${p.code.toLowerCase()}@okbank` : null,
      experience: "I advise local businesses on accounts and IT.",
    });
    return user;
  }

  const anu = await createPartner({ email: "partner@corpus365.test", name: "Anu Thomas", city: "Kochi", region: "Kerala", code: "ANU365", profession: "Accountant / bookkeeper", status: "approved", approvedDaysAgo: 420 });
  const rahul = await createPartner({ email: "rahul@corpus365.test", name: "Rahul Menon", city: "Bengaluru", region: "Karnataka", code: "RAHUL24", profession: "IT shop / reseller", status: "approved", approvedDaysAgo: 40 });
  await createPartner({ email: "priya@corpus365.test", name: "Priya Nair", city: "Thrissur", region: "Kerala", code: "PRIYA88", profession: "Business consultant", status: "pending" });
  await createPartner({ email: "farhan@corpus365.test", name: "Farhan Ali", city: "Kozhikode", region: "Kerala", code: "FARHAN7", profession: "Freelancer", status: "pending" });

  async function createClient(c: { email?: string; name: string; company: string; city: string; daysAgo: number }) {
    return single(
      db
        .insert(t.users)
        .values({
          email: c.email ?? `${c.company.toLowerCase().replace(/[^a-z]+/g, ".").replace(/^\.|\.$/g, "")}@example.com`,
          name: c.name,
          companyName: c.company,
          city: c.city,
          role: "client",
          phone: "+91 90000 00000",
          passwordHash: passwordHash.client,
          createdAt: daysAgo(c.daysAgo),
        })
        .returning(),
    );
  }

  async function buy(user: t.User, slug: string, interval: "month" | "year", whenDaysAgo: number, partnerCode?: string) {
    await checkout({
      buyer: user,
      lines: [{ productId: product(slug).id, planId: plan(slug, interval).id, quantity: 1 }],
      billing: { billingName: user.name, billingCompany: user.companyName },
      partnerCode,
      now: daysAgo(whenDaysAgo),
    });
  }

  async function renewYearly(user: t.User, slug: string, whenDaysAgo: number) {
    const sub = await single(
      db.select().from(t.subscriptions).where(and(eq(t.subscriptions.userId, user.id), eq(t.subscriptions.productId, product(slug).id))),
    );
    await renewSubscription({ subscriptionId: sub.id, now: daysAgo(whenDaysAgo) });
  }

  /* ---------------------------------------------------- Anu's book (Silver) */
  const demoClient = await createClient({ email: "client@corpus365.test", name: "Joseph Kurian", company: "Iron Temple Gym", city: "Kochi", daysAgo: 400 });
  await buy(demoClient, "fitness-center-management", "year", 395, "ANU365");
  await renewYearly(demoClient, "fitness-center-management", 30);
  await checkout({
    buyer: demoClient,
    lines: [{ productId: product("biometric-attendance").id, planId: null, quantity: 2 }],
    billing: { billingName: demoClient.name, billingCompany: demoClient.companyName },
    now: daysAgo(390),
  });

  const anuClients: [string, string, string, string, "month" | "year", number][] = [
    ["Meera Das", "FitZone Studio", "Kochi", "fitness-center-management", "year", 380],
    ["Arjun Pillai", "St. Mary's Public School", "Thrissur", "school-erp-management", "year", 375],
    ["Sneha Varghese", "Pulse Fitness", "Kottayam", "fitness-center-management", "year", 300],
    ["Rakesh Nambiar", "Green Valley School", "Kochi", "school-erp-management", "year", 240],
    ["Fathima Rasheed", "Core Strength Gym", "Kozhikode", "fitness-center-management", "month", 200],
    ["Vivek Raj", "Little Flower Academy", "Aluva", "school-erp-management", "year", 150],
    ["Divya Menon", "Yoga Shala Kochi", "Kochi", "fitness-center-management", "year", 120],
    ["Thomas Mathew", "Riverside International School", "Kottayam", "school-erp-management", "year", 90],
    ["Kavya Suresh", "PowerHouse Gym", "Thrissur", "fitness-center-management", "year", 60],
    ["Nikhil George", "Bright Minds School", "Kollam", "school-erp-management", "month", 45],
    ["Asha Joseph", "Flex Fitness", "Kochi", "fitness-center-management", "year", 20],
    ["Manoj Kumar", "Sunrise CBSE School", "Palakkad", "school-erp-management", "year", 10],
  ];
  const seeded: t.User[] = [];
  for (const [name, company, city, slug, interval, when] of anuClients) {
    const client = await createClient({ name, company, city, daysAgo: when + 3 });
    await buy(client, slug, interval, when, "ANU365");
    seeded.push(client);
  }
  // Yearly clients from over a year ago renewed (one did not, and lapsed).
  await renewYearly(seeded[0]!, "fitness-center-management", 15);
  await renewYearly(seeded[1]!, "school-erp-management", 10);
  await db.update(t.subscriptions).set({ status: "expired" }).where(eq(t.subscriptions.userId, seeded[2]!.id));
  // Monthly clients are due now, so the billing job has work to show.
  for (const monthly of [seeded[4]!, seeded[9]!]) {
    await db.update(t.subscriptions).set({ currentPeriodEnd: daysAgo(1) }).where(eq(t.subscriptions.userId, monthly.id));
  }

  // A prospect trying the app via Anu's link.
  const trialClient = await createClient({ name: "Leena Francis", company: "Zen Pilates", city: "Kochi", daysAgo: 4 });
  await db.update(t.users).set({ referredByPartnerId: anu.id }).where(eq(t.users.id, trialClient.id));
  await startTrial({ userId: trialClient.id, productId: product("fitness-center-management").id, now: daysAgo(4) });

  /* ----------------------------------------------- Rahul's book (new partner) */
  for (const [name, company, when] of [
    ["Sanjay Rao", "Iron Paradise Gym", 35],
    ["Lakshmi Iyer", "Vidya Niketan School", 20],
    ["Karthik Gowda", "BeFit Koramangala", 5],
  ] as const) {
    const client = await createClient({ name, company, city: "Bengaluru", daysAgo: when + 2 });
    await buy(client, company.includes("School") ? "school-erp-management" : "fitness-center-management", "year", when, "RAHUL24");
  }
  await placePartnerBulkOrder({
    partner: rahul,
    lines: [
      { productId: product("thermal-receipt-printer").id, quantity: 5 },
      { productId: product("fitness-center-management").id, quantity: 10 },
    ],
    now: daysAgo(25),
  });

  // A business that bought directly, with no partner.
  const direct = await createClient({ name: "Ravi Shankar", company: "Spark Gym Trivandrum", city: "Thiruvananthapuram", daysAgo: 70 });
  await buy(direct, "fitness-center-management", "month", 1);

  /* ------------------------------------------------------- payouts & leads */
  for (const monthsAgo of [3, 2, 1]) {
    const runAt = daysAgo(monthsAgo * 30);
    const { created } = await generatePayouts(admin.id, runAt);
    if (created === 0 || monthsAgo === 1) continue; // leave last month's for the admin to pay
    for (const payout of await db.select().from(t.payouts).where(eq(t.payouts.status, "pending"))) {
      await markPayoutPaid(admin.id, payout.id, `UPI-${payout.period}-${payout.partnerId.slice(0, 6).toUpperCase()}`, addDays(runAt, 2));
    }
  }

  await db.insert(t.leads).values([
    { partnerId: anu.id, businessName: "Muscle Factory", contactName: "Ajay K", phone: "+91 94470 11111", productId: product("fitness-center-management").id, status: "demo", notes: "Demo booked for Saturday." },
    { partnerId: anu.id, businessName: "Holy Cross School", contactName: "Sr. Mercy", email: "office@holycross.example", productId: product("school-erp-management").id, status: "contacted" },
    { partnerId: anu.id, businessName: "Fresh Mart", contactName: "Shaji P", phone: "+91 94470 22222", productId: product("barcode-scanner").id, status: "new", notes: "Wants scanners + Lite when it launches." },
    { partnerId: anu.id, businessName: "Zen Pilates", contactName: "Leena Francis", email: "leena@zenpilates.example", productId: product("fitness-center-management").id, status: "trial" },
  ]);

  await db.insert(t.quoteRequests).values({
    productId: product("gym-access-control").id,
    name: "Joseph Kurian",
    email: "client@corpus365.test",
    phone: "+91 90000 00000",
    city: "Kochi",
    message: "Two turnstiles at the main entrance.",
    userId: demoClient.id,
    partnerId: anu.id,
  });

  console.log(`Seeded. Sign in with:
  admin@corpus365.test   / Admin@12345
  partner@corpus365.test / Partner@12345
  client@corpus365.test  / Client@12345`);
}

main()
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(() => closeDb());
